// ===== CATATAN RILIS (v1.1.003): data untuk modal "?" di Setelan. Tambahkan rilis baru di PALING ATAS; sinkronkan dengan release_notes.md =====
const RELEASES=[
 {v:"1.1.114",d:"2026-10-07",t:"Pengaturan Awan pindah ke Data > Backup",i:["Koneksi, akun, simpan dan muat dari awan kini ada di halaman Data > Backup, bagian Sinkron ke awan.","Tab Awan di Setelan dihapus."]},
 {v:"1.1.113",d:"2026-10-07",t:"Profil BUMDes ikut tersinkron dengan awan",i:["Nama, alamat, dan logo BUMDes kini ikut disimpan ke awan dan ikut dimuat dari awan bersama datanya.","Import JSON dan Kosongkan data tetap tidak mengubah profil BUMDes."]},
 {v:"1.1.112",d:"2026-10-07",t:"Sinkron awan hanya untuk data",i:["Muat dari awan dan pemulihan riwayat versi hanya mengganti data; nama, alamat, dan logo BUMDes di perangkat tidak berubah.","Perangkat baru yang profilnya belum diisi otomatis memakai profil dari awan."]},
 {v:"1.1.111",d:"2026-10-07",t:"Data & Cadangan lebih jelas dan aman",i:["Halaman Data > Backup kini punya tiga bagian: Cadangkan, Pulihkan, dan Kosongkan semua data.","Import hanya mengganti data; nama, alamat, dan logo BUMDes tidak ikut berubah.","Kosongkan semua data meminta Anda mengetik KOSONGKAN dan menyimpan salinan lama di perangkat; profil BUMDes, pengguna, dan pengaturan tetap."]},
 {v:"1.1.110",d:"2026-10-07",t:"Nama BUMDes seragam di aplikasi dan awan",i:["Nama BUMDes di Profil dan nama di awan kini disamakan: nama yang diisi saat Siapkan BUMDes menjadi nama Profil.","Admin yang menyimpan Profil BUMDes atau memuat data dari awan ikut memperbarui nama di awan."]},
 {v:"1.1.109",d:"2026-10-07",t:"Layar Siapkan BUMDes lebih jelas saat gagal",i:["Pesan kesalahan kini tampil tetap di kotak merah, bukan hilang sendiri, dan semua isian yang salah disebutkan sekaligus.","Kata sandi tidak terhapus saat gagal, dan ada ikon mata untuk menampilkan atau menyembunyikan kata sandi, juga di layar Masuk.","Bila Supabase tidak menjawab dalam 25 detik, muncul pesan agar memeriksa internet."]},
 {v:"1.1.108",d:"2026-10-07",t:"Berkas SQL dirapikan bertahap",i:["Semua berkas SQL kini ada di folder sql/ dengan nama berurutan: 00_semua untuk pasang sekaligus, 01 sampai 07 untuk bertahap, dan 99_reset untuk mengosongkan database."]},
 {v:"1.1.107",d:"2026-10-07",t:"Satu aplikasi, satu database, satu BUMDes",i:["Setiap BUMDes kini memakai aplikasi dan database sendiri; daftar BUMDes dan peran developer dihapus.","Pertama kali dipakai, layar Siapkan BUMDes meminta nama, email, dan kata sandi; pendaftar pertama otomatis menjadi admin.","Pengurus lain ditambahkan oleh admin di Setelan > Pengguna & Peran."]},
 {v:"1.1.106",d:"2026-10-07",t:"Cek peran akun developer atau admin",i:["Setelan > Awan punya tombol Cek peran akun yang menjelaskan apakah akun ini developer platform atau akun BUMDes biasa.","Bila pengecekan developer gagal (misalnya SQL developer belum terpasang), penyebabnya kini ditampilkan."]},
 {v:"1.1.105",d:"2026-10-07",t:"Halaman Setelan Awan dibedakan untuk developer dan admin",i:["Akun developer kini melihat kartu Konsol Developer dan jumlah BUMDes klien, tanpa menu sinkron dan tabel yang khusus akun BUMDes.","Akun admin atau pengurus tetap melihat sinkron, riwayat, dan tabel BUMDes-nya."]},
 {v:"1.1.104",d:"2026-10-07",t:"Halaman Setelan Awan lebih rapi di komputer",i:["Di layar lebar, Setelan > Awan kini dua kolom: sinkron, riwayat, dan tabel di kiri; koneksi, BUMDes, dan kata sandi di kanan.","Di HP tampilan tetap satu kolom."]},
 {v:"1.1.103",d:"2026-10-07",t:"Data penjualan, Unit Air, jaminan, dan tarif masuk tabel Supabase",i:["Penjualan, tagihan dan meter air, jaminan pinjaman, tarif, pajak, catatan penagihan, dan calon peminjam kini ikut disalin ke tabel di Supabase beserta pengecekan kecocokan (butuh menjalankan supabase_tahap5.sql sekali).","Berkas SQL kini 8; untuk proyek baru cukup jalankan supabase_semua.sql."]},
 {v:"1.1.102",d:"2026-10-07",t:"Developer bisa masuk ke login BUMDes pilihan",i:["Di halaman Developer, setiap BUMDes aktif punya tombol Masuk ke BUMDes yang membuka layar login BUMDes tersebut.","Setelah masuk dengan akun admin atau pengurus BUMDes itu, aplikasi langsung membuka BUMDes yang dituju; akun lain ditolak dengan pesan jelas."]},
 {v:"1.1.101",d:"2026-10-07",t:"Data tabungan ikut masuk tabel Supabase",i:["Rekening dan mutasi tabungan kini ikut disalin ke tabel di Supabase beserta pengecekan kecocokan saldo (butuh menjalankan supabase_tahap4.sql).","Berkas SQL dirapikan menjadi 7 berkas bernomor berurutan; untuk proyek baru cukup tempel supabase_semua.sql.","Daftar BUMDes di Setelan > Awan hanya menampilkan BUMDes milik akun yang masuk, tanpa duplikat dan dengan peran yang benar."]},
 {v:"1.1.100",d:"2026-10-07",t:"Alamat untuk semua sub-tab",i:["Sub-tab di Laporan, Simpan Pinjam, Master, Transaksi, Gaji, Unit Air, dan Data kini punya alamat sendiri, misalnya /laporan/laba-rugi atau /simpan-pinjam/tunggakan.","Tombol Kembali, refresh, dan tautan langsung membuka sub-tab yang sama."]},
 {v:"1.1.099",d:"2026-10-07",t:"Cetak laporan lebih rapi",i:["Laporan tercetak di kertas A4 dengan kop BUMDes, tabel yang jelas, kepala tabel berulang di tiap halaman, dan nomor halaman.","Kartu ringkasan dan tombol pilihan tidak lagi ikut tercetak, dan tema gelap tetap tercetak hitam di atas putih.","Di akhir laporan ada kolom tanda tangan Bendahara dan Direktur serta catatan tanggal cetak."]},
 {v:"1.1.098",d:"2026-10-06",t:"Alamat per halaman",i:["Setiap menu kini punya alamat sendiri, misalnya /laporan atau /setelan/awan.","Tombol Kembali di browser berfungsi, halaman bisa disimpan sebagai bookmark atau dibagikan, dan refresh tetap di halaman yang sama."]},
 {v:"1.1.097",d:"2026-10-06",t:"Dua BUMDes di awan kini punya data terpisah",i:["Memilih atau membuat BUMDes lain di Setelan > Awan tidak lagi menyalin data perangkat ke BUMDes itu.","BUMDes baru mulai kosong; BUMDes yang sudah berisi dimuat dari awan. Data sebelumnya tetap aman di awan dan dicadangkan di perangkat.","Berpindah ditahan bila masih ada perubahan yang belum disimpan ke awan."]},
 {v:"1.1.096",d:"2026-10-06",t:"Setelan lebih lega di semua tab",i:["Di layar lebar, kartu Modul dan pengaturan Simpan Pinjam kini tampil dua kolom sehingga tidak perlu menggulir panjang.","Di ponsel tampilan tetap satu kolom."]},
 {v:"1.1.095",d:"2026-10-06",t:"Setelan Profil lebih lega di desktop",i:["Di layar lebar, isian Profil BUMDes tampil dua kolom dengan pengaturan Dokumen Cetak di sebelahnya.","Di ponsel tampilan tetap satu kolom seperti biasa."]},
 {v:"1.1.094",d:"2026-10-04",t:"Buku Besar lebih ringkas dan lengkap",i:["Ada ringkasan saldo akhir, total debit, total kredit, dan jumlah mutasi di atas daftar.","Pilihan akun dikelompokkan per tipe dan menunjukkan jumlah mutasinya.","Sentuh baris untuk membuka rincian transaksi; di HP tiap mutasi hanya dua baris.","Tampil saldo awal bila memilih tanggal awal; urutan bisa terlama atau terbaru dulu; bisa dicetak atau diunduh CSV."]},
 {v:"1.1.093",d:"2026-10-04",t:"SQL Supabase dirapikan",i:["Berkas SQL untuk Supabase kini seragam dan bernomor urutan pasang.","Tersedia satu berkas, supabase_semua.sql, untuk memasang semuanya sekaligus di proyek baru.","Panduan SUPABASE.md ditulis ulang agar lebih mudah diikuti."]},
 {v:"1.1.092",d:"2026-10-04",t:"Sidebar lebih ringan",i:["Tombol Ciutkan di dasar menu diganti tombol bulat kecil di tepi sidebar.","Menu aktif ditandai warna hijau muda, logo tampil dalam kotak, dan mode ciut lebih rapi."]},
 {v:"1.1.091",d:"2026-10-04",t:"Laporan tampil lebih rapi",i:["Halaman Laporan kini diawali kartu ringkasan: total aset, pendapatan, beban, laba atau rugi, dan kas.","Pilihan laporan berupa kartu berikon dengan angka kunci masing-masing; isi laporan tidak berubah.","Di HP, tabel dua kolom tidak lagi memotong angka."]},
 {v:"1.1.090",d:"2026-10-04",t:"Dashboard tampil seperti dasbor analitik",i:["Kartu ringkasan kini punya ikon dan penanda naik/turun dibanding bulan lalu.","Kartu baru: Ringkasan Bulan Ini, Pendapatan per Unit, dan Pola Transaksi per Hari.","Tren 6 Bulan berupa grafik area dengan angka total di sampingnya.","Saldo Kas & Bank menampilkan total besar, bar komposisi, dan persentase tiap rekening."]},
 {v:"1.1.089",d:"2026-10-04",t:"Dashboard lebih informatif",i:["Kartu baru: angsuran yang jatuh tempo dalam 7 hari ke depan dan total tabungan nasabah.","Kartu laba/rugi menampilkan margin dari pendapatan.","Daftar peringatan diringkas menjadi 3 teratas, bisa dibuka semua.","Ada daftar transaksi terakhir, total saldo kas, dan penjelasan selisih antara total dan laba rugi per unit."]},
 {v:"1.1.088",d:"2026-10-04",t:"Halaman Master lebih ringkas",i:["Chart of Accounts, Mitra, Pegawai, dan Tarif & Biaya kini punya kolom cari; akun bisa difilter menurut tipe dan pegawai menurut status.","Unit Usaha, Kas & Bank, dan akun menampilkan jumlahnya.","Daftar jabatan di Pegawai dilipat bawaan sehingga halaman tidak terlalu panjang."]},
 {v:"1.1.087",d:"2026-10-04",t:"Setelan lebih rapi",i:["Halaman Setelan ditata ulang: urutan tab kini Profil, Pengguna & Peran, Modul, Simpan Pinjam, Portal Nasabah, lalu Awan.","Semua pengaturan Simpan Pinjam yang sebelumnya menumpuk di tab Profil dipindah ke tab Simpan Pinjam sendiri, dikelompokkan dalam lima bagian yang bisa dilipat: Jasa, denda, nomor, batas; Alur, kontrol, dan kolektibilitas; Tabungan dan deposito; Akuntansi fee; Dokumen dan penagihan.","Tab Profil kini hanya berisi profil BUMDes, logo, dan penandatangan. Isi pengaturan tidak berubah."]},
 {v:"1.1.086",d:"2026-10-04",t:"Pegawai dan gaji masuk tabel Supabase",i:["Data pegawai, komponen gaji, gaji, rincian gaji, dan pembayaran gaji kini ikut disalin ke tabel di Supabase (Setelan > Awan > Tabel relasional), lengkap dengan pengecekan kecocokan dan total gaji bersih.","Perlu menjalankan supabase_tahap3.sql sekali di SQL Editor. Sebelum itu dipasang, semuanya tetap aman di cadangan lengkap dan menu tabel berjalan seperti biasa."]},
 {v:"1.1.085",d:"2026-10-04",t:"Pengguna dari pegawai, PIN awal 1234",i:["Tombol Buat pengguna dari pegawai (menu Pengguna): tiap pegawai aktif yang belum punya akun dibuatkan pengguna otomatis, dengan peran sesuai jabatannya (diatur di Daftar jabatan) dan unit tugas sesuai unit pegawai.","PIN awal 1234. Saat masuk pertama, pengguna wajib menggantinya, dan PIN baru tidak boleh tetap 1234. Di form Tambah pengguna, PIN boleh dikosongkan untuk memakai 1234.","Tersedia juga query SQL (supabase_pengguna.sql) untuk membuat pengguna yang sama langsung di database Supabase."]},
 {v:"1.1.084",d:"2026-10-04",t:"Jabatan umum langsung tersedia",i:["Daftar jabatan tidak lagi kosong: Direktur, Sekretaris, Bendahara, Kepala Unit Usaha, Kasir, Petugas Unit, Petugas Kredit, Surveyor/Analis, dan Staf Administrasi terisi otomatis sekali, lengkap dengan peran pengguna bawaan.","Di Master > Pegawai ada tombol Isi jabatan umum untuk mengembalikan jabatan yang terhapus. Jabatan yang sudah ada tidak digandakan."]},
 {v:"1.1.083",d:"2026-10-04",t:"Dokumen dirapikan",i:["Tidak ada perubahan tampilan aplikasi. Dokumen proyek dirapikan dan diringkas, dan riwayat rilis lama dipindah ke arsip agar dokumen utama ringan."]},
 {v:"1.1.082",d:"2026-10-04",t:"Pengguna dipilih dari daftar pegawai",i:["Saat menambah pengguna, pilih pegawai dari daftar: nama, unit tugas, dan peran terisi otomatis. Satu pegawai hanya bisa punya satu akun; mengisi manual tetap bisa.","Peran bawaan diatur per jabatan (Master > Pegawai > Daftar jabatan > edit), jadi memilih pegawai langsung memberi peran yang sesuai jabatannya."]},
 {v:"1.1.081",d:"2026-10-04",t:"Daftar jabatan & komponen gaji persen/laba",i:["Jabatan pegawai kini dipilih dari daftar (master jabatan), bukan diketik tiap kali. Di form Tambah pegawai ada pilihan Jabatan dan isian Jabatan baru bila belum ada di daftar; jabatan baru otomatis masuk daftar.","Master > Pegawai punya bagian Daftar jabatan: tambah jabatan, lihat jumlah pegawai per jabatan, dan hapus jabatan yang tidak dipakai.","Jabatan dari pegawai yang sudah ada otomatis masuk daftar, dan penulisan dengan huruf berbeda disatukan agar tidak ganda.","Komponen gaji (Gaji > Komponen) kini punya cara hitung: nominal tetap, persen dari gaji pokok, atau persen dari laba. Untuk persen laba bisa dipilih laba sebelum atau sesudah beban gaji; bila laba rugi, komponen otomatis bernilai 0.","Form pegawai memakai ceklist komponen (seperti biaya pencairan pinjaman): centang komponen dan isi nilainya, lalu otomatis ikut saat gaji dibuat. Nama komponen di slip menampilkan persentasenya.","Tiap jabatan bisa diberi gaji standar dan komponen bawaan (tombol edit di Daftar jabatan); memilih jabatan di form pegawai baru langsung mengisi gaji dan ceklist."]},
 {v:"1.1.080",d:"2026-10-04",t:"Masuk lebih aman di perangkat berisi data",i:["Bila perangkat sudah berisi data dan awan juga sudah punya data, aplikasi tidak lagi menimpa data perangkat secara otomatis. Sinkron dijeda dan Anda memilih Muat dari awan atau Timpa awan.","Layar pilih BUMDes kini menampilkan versi data, tanggal, atau tulisan kosong, dan kode singkat bila namanya kembar, dengan yang berisi data di urutan pertama.","Status sinkron menulis Belum pernah disinkron (bukan Tersinkron) sebelum ada penyimpanan pertama."]},
 {v:"1.1.079",d:"2026-10-04",t:"Satu halaman masuk untuk semua peran",i:["Saat aplikasi dibuka tanpa sesi, yang tampil adalah halaman masuk dengan cover. Pengurus dan developer mengisi email, nasabah mengisi nomor HP. Setelah cocok, Anda langsung diarahkan sesuai peran: developer ke konsol developer, admin dan pengurus ke aplikasi, pembaca ke aplikasi (hanya lihat), nasabah ke portal.","Di perangkat baru, data BUMDes dimuat otomatis dari awan setelah masuk. Bila akun terdaftar di beberapa BUMDes, ada layar pilih BUMDes. Perangkat lama yang sudah berisi data dan belum pernah masuk punya satu tombol untuk memakai data lokal.","Sesi tersimpan di perangkat: selama belum Keluar, aplikasi dan portal nasabah tetap terbuka walau tanpa internet. Masuk pertama kali tetap butuh internet.","Nasabah kini bisa masuk dari HP sendiri dengan nomor HP dan PIN. Pengurus mengatur PIN seperti biasa, datanya diterbitkan otomatis ke server saat menyimpan ke awan, dan nasabah hanya melihat datanya sendiri. Portal bisa dibuka offline dari salinan terakhir, PIN bisa diganti sendiri, dan salah PIN berulang mengunci akun bertahap.","Pembaca di awan kini hanya bisa melihat: tombol dan aksi yang mengubah data ditolak. Server tetap menjadi penjaga utama."]},
 {v:"1.1.078",d:"2026-10-04",t:"Halaman khusus developer",i:["Akun developer kini punya halaman khusus seperti portal nasabah: di desktop dengan menu samping, di HP dengan menu bawah. Dibuka lewat tombol di Setelan > Awan atau alamat dengan akhiran #developer.","Isinya: Ringkasan (jumlah BUMDes, aktif, nonaktif, kosong, nama kembar, ukuran, dan hal yang perlu diperhatikan), daftar BUMDes dengan pencarian dan filter, Tambah (buat BUMDes dan admin), serta Aturan dan catatan tindakan.","Konfirmasi untuk menonaktifkan dan menghapus tampil di dalam halaman itu."]},
 {v:"1.1.077",d:"2026-10-04",t:"Peran developer platform",i:["Akun developer punya bagian Developer di Setelan > Awan untuk melihat semua BUMDes (nama, anggota, admin, versi data, ukuran), membuat BUMDes untuk klien dengan admin pertamanya, menambah admin, menonaktifkan atau mengaktifkan, dan menghapus BUMDes yang masih kosong.","Developer tidak bisa membaca isi data nasabah dan transaksi BUMDes, kecuali ditambahkan sebagai anggota.","Developer bisa membatasi pembuatan BUMDes baru hanya untuk developer, dan semua tindakannya tercatat."]},
 {v:"1.1.076",d:"2026-10-03",t:"Daftar BUMDes awan lebih jelas",i:["Pilihan BUMDes di awan kini menampilkan versi data dan tanggal terakhir (atau tulisan kosong), sehingga BUMDes bernama sama mudah dibedakan.","Muncul peringatan bila ada nama kembar, dan membuat BUMDes baru dengan nama yang sudah ada ditolak agar tidak terbuat ganda."]},
 {v:"1.1.075",d:"2026-10-03",t:"Tabel relasional di Supabase",i:["Setelan > Awan punya bagian Tabel relasional: tombol Isi tabel sekarang menyalin data ke tabel Supabase (unit, pihak, akun, transaksi, jurnal, pinjaman, angsuran, pembayaran, audit).","Server menolak jurnal yang tidak seimbang, dan Cek kecocokan membandingkan jumlah baris serta total debit, kredit, dan pokok pinjaman antara perangkat dan server.","Bisa diaktifkan otomatis setiap kali data disimpan ke awan. Snapshot tetap menjadi cadangan utama; pengurus kini boleh mengisi tabel, tidak hanya admin."]},
 {v:"1.1.074",d:"2026-10-03",t:"Halaman masuk awan",i:["Ada halaman masuk khusus untuk akun awan: di desktop tampil dengan cover dan keunggulan di sisi kiri, di HP form tampil penuh dengan header ringkas.","Di Setelan > Awan, bila belum masuk ada tombol Masuk ke akun awan yang membuka halaman itu; bila sudah masuk cukup tombol Keluar. Ganti kata sandi tetap ada di bagian lipat.","Halaman masuk juga bisa dibuka lewat alamat dengan akhiran #masuk. Tersedia tombol tampilkan kata sandi dan Lupa kata sandi."]},
 {v:"1.1.073",d:"2026-10-03",t:"Tab Awan lebih ringkas",i:["Tab Awan di Setelan kini diawali ringkasan: koneksi, akun, BUMDes awan, status sinkron, dan langkah berikutnya.","Tombol Simpan, Muat, dan Sinkron otomatis tampil di bagian atas; koneksi, akun, dan pilihan BUMDes terlipat otomatis setelah selesai.","Kata sandi bisa dikirim dengan tombol Enter saat masuk."]},
 {v:"1.1.072",d:"2026-10-03",t:"Koneksi awan sudah tertanam",i:["Alamat proyek dan kunci publik Supabase sudah diisi di aplikasi, jadi pengurus langsung bisa masuk di Setelan > Awan tanpa mengetik koneksi."]},
 {v:"1.1.071",d:"2026-10-03",t:"Akun awan dan sinkron otomatis dua arah",i:["Koneksi Supabase bisa diatur langsung di config.js sehingga pengurus tidak perlu mengetik alamat dan kunci di Setelan.","Di Setelan > Awan ada Lupa kata sandi (tautan lewat email), layar kata sandi baru, dan Ganti kata sandi saat sudah masuk.","Status sinkron tampil jelas (tersinkron, menunggu, offline, dijeda) dan muncul pengingat bila cadangan awan tertunda 7 hari atau lebih.","Sinkron otomatis kini dua arah: data baru dari perangkat lain diambil saat aplikasi dibuka atau kembali online, selama tidak ada perubahan yang belum terkirim."]},
 {v:"1.1.070",d:"2026-10-03",t:"Pengingat penagihan dan laporan tabungan wajib",i:["Sub-tab Tunggakan menampilkan daftar pinjaman yang menunggak atau jatuh tempo dalam 7 hari, lengkap dengan teks pengingat siap salin, kirim lewat WhatsApp, atau bagikan. Teksnya bisa diubah di Setelan.","Laporan Simpan Pinjam menampilkan tabungan wajib per pinjaman: dipotong, masih terkunci, dan sudah dikembalikan."]},
 {v:"1.1.069",d:"2026-10-03",t:"Kualitas portofolio pinjaman",i:["Sub-tab Tunggakan dan laporan Simpan Pinjam menampilkan PAR (pinjaman berisiko) 30, 60, dan 90 hari, distribusi umur tunggakan, serta persentase pinjaman bermasalah terhadap total pinjaman aktif.","Laporan pendapatan kini juga memuat akun fee per jenis bila pemisahan akun fee diaktifkan."]},
 {v:"1.1.068",d:"2026-10-03",t:"Denda dari Master Tarif & Biaya",i:["Di Setelan, denda keterlambatan bisa mengikuti tarif di Master Tarif & Biaya sehingga punya versi dan tanggal berlaku. Tombol Pindahkan denda memindahkan angka yang sekarang tanpa mengubah hasil hitung.","Denda yang sudah berjalan tidak berubah; tarif baru hanya dipakai untuk hitungan berikutnya."]},
 {v:"1.1.067",d:"2026-10-03",t:"Pendapatan fee dipisah per jenis",i:["Di Setelan, pilih mencatat pendapatan fee ke akun terpisah: administrasi, provisi, materai, transfer, pelunasan dipercepat, dan restrukturisasi. Laporan laba rugi jadi lebih rinci.","Pilihan bawaan tetap satu akun. Berlaku untuk transaksi berikutnya; catatan lama tidak berubah."]},
 {v:"1.1.066",d:"2026-10-03",t:"Status tabungan wajib lebih jelas",i:["Rincian pinjaman menampilkan tabungan wajib dan statusnya: terkunci, dikembalikan, atau bebas ditarik.","Saat pinjaman dihapus buku, aplikasi memberi tahu bahwa tabungan wajib tetap milik nasabah dan tidak lagi terkunci. Pembatalan pembayaran pelunasan ditolak bila rekening tabungan wajibnya sudah ditutup."]},
 {v:"1.1.065",d:"2026-10-03",t:"Ubah pengajuan ikut master",i:["Saat mengubah draf atau pengajuan yang belum disetujui, jasa kini otomatis dari tarif di Master Tarif & Biaya (tidak bisa diketik), dan biaya pencairan, jumlah materai, serta tabungan wajib bisa dicentang ulang.","Pratinjau biaya dan angsuran tampil langsung. Pinjaman yang sudah disetujui tetap tidak dapat diubah."]},
 {v:"1.1.064",d:"2026-10-03",t:"Atur perlakuan tabungan wajib",i:["Di Setelan, pilih tabungan wajib bebas ditarik, terkunci sampai pinjaman lunas, atau terkunci lalu dikembalikan otomatis ke nasabah saat lunas.","Berlaku untuk pencairan berikutnya. Bila pembayaran pelunasan dibatalkan, pengembalian otomatisnya ikut dibatalkan."]},
 {v:"1.1.063",d:"2026-10-03",t:"Tabungan wajib saat pencairan",i:["Master Tarif & Biaya punya jenis Tabungan wajib (persen atau nominal). Saat pinjaman dicairkan, bagian ini otomatis masuk ke rekening Tabungan Wajib milik nasabah dan mengurangi dana yang diterima.","Muncul di ceklist biaya dan pratinjau form pengajuan. Bila pencairan dibatalkan, tabungan wajibnya ikut dibatalkan (tidak bisa jika sudah ditarik)."]},
 {v:"1.1.062",d:"2026-10-03",t:"Jumlah materai di form pengajuan",i:["Di ceklist biaya pencairan, biaya bernominal tetap seperti materai dan transfer punya kolom jumlah. Isi 2 bila dokumen memerlukan dua materai: potongannya otomatis dikali, dan pratinjau menampilkan Materai ×2.","Pajak (bila biaya kena pajak) dihitung dari total setelah dikali. Pinjaman lama tetap satu materai."]},
 {v:"1.1.061",d:"2026-10-03",t:"Jasa dari master dan ceklist biaya di form pengajuan",i:["Di form Ajukan pinjaman, kolom Jasa kini terkunci: nilainya selalu mengikuti tarif jasa di Master > Tarif & Biaya (menurut pokok dan tanggal). Untuk mengubah angkanya, ubah tarif di master.","Ada ceklist biaya pencairan (administrasi, provisi, materai, transfer, dan lain-lain): centang biaya yang berlaku untuk pinjaman itu. Pratinjau dan dana bersih langsung mengikuti, dan pilihan tersimpan pada pinjaman sampai pencairan.","Pinjaman lama tidak berubah: tetap mengikuti pengaturan di Setelan > Simpan Pinjam."]},
 {v:"1.1.060",d:"2026-10-03",t:"Data contoh lengkap dan perbaikan impor backup",i:["Perbaikan: backup yang memuat pinjaman berstatus Dihapus buku sebelumnya gagal diimpor atau dipulihkan dari awan. Sekarang berhasil.","Tersedia berkas data contoh lengkap (bumdes-data-lengkap.json): nasabah, pinjaman di semua status, tabungan, Unit Air, Perdagangan, gaji, dan master tarif. Impor lewat Setelan > Data > Import JSON."]},
 {v:"1.1.059",d:"2026-10-03",t:"Kode otomatis untuk biaya, pajak, unit, akun, dan akad",i:["Saat menambah tarif biaya, kode terisi otomatis menurut jenis (ADM001, PRV001, MTR001, dan seterusnya) dan ikut berubah saat jenis diganti. Pajak: PJK001. Unit usaha: UNT001. Akun: kode 4 digit menurut tipe akun. Semua boleh diganti dengan kode sendiri, atau dibiarkan kosong.","Nomor akad kini otomatis memuat tahun dan bulan (AKD/202610/0001) dengan format yang dapat diatur di Setelan > Simpan Pinjam, dan tetap bisa diubah saat membuat akad."]},
 {v:"1.1.058",d:"2026-10-03",t:"Nomor pinjaman memuat tahun dan bulan",i:["Nomor pinjaman baru berbentuk LN-202610-0001: memuat tahun dan bulan pengajuan, dengan nomor urut otomatis yang mulai 1 lagi tiap bulan. Draf memakai DRF-202610-0001.","Formatnya dapat diatur di Setelan > Simpan Pinjam, misalnya SP/{YY}{MM}{DD}/{NNN} untuk memuat tanggal juga. Contoh nomor berikutnya langsung terlihat.","Nomor pinjaman yang sudah ada tidak berubah."]},
 {v:"1.1.057",d:"2026-10-03",t:"Jasa bertingkat menurut pokok dari master",i:["Di Master > Tarif & Biaya, metode Bertingkat untuk jenis Jasa: atur persentase menurut besar pokok, misalnya pokok di bawah 10 juta 2% per bulan, di bawah 50 juta 1,75%, dan seterusnya 1,5%.","Di form Ajukan pinjaman, pilih tarif bertingkat itu: kolom Jasa terisi sendiri dan berubah mengikuti pokok yang diketik, lengkap dengan keterangan tingkatnya.","Seluruh pokok memakai satu persentase sesuai tingkatnya. Tombol Isi data contoh menambahkan contoh BUNGATGKT."]},
 {v:"1.1.056",d:"2026-10-03",t:"Form pengajuan menampilkan tarif, biaya, dan pajak dari master",i:["Di form Ajukan pinjaman ada blok Tarif, biaya & pajak dari Master: daftar biaya pencairan beserta rumusnya dan pajak yang berlaku, langsung terlihat sebelum Anda mengisi angka.","Setelah pokok dan tenor diisi, tampil nominal tiap biaya, pajak (misalnya PPN 11%), total, dan dana bersih yang diterima nasabah.","Data contoh: administrasi dan transfer kini dikenai PPN. Klik Isi data contoh lagi untuk memperbarui contoh lama."]},
 {v:"1.1.055",d:"2026-10-03",t:"Data contoh untuk Master Tarif & Biaya",i:["Di Master > Tarif & Biaya ada tombol Isi data contoh: tiga tarif jasa (12%, 18%, 24%), administrasi, materai, transfer, denda, biaya pelunasan, dan PPN 11%. Aman diklik berulang; yang sudah ada tidak digandakan. Ubah sesuai kebijakan BUMDes."]},
 {v:"1.1.054",d:"2026-10-03",t:"Jasa dan biaya pinjaman baru dari Master Tarif & Biaya",i:["Saat mengajukan pinjaman, Anda bisa memilih tarif jasa dari Tarif & Pajak; kolom jasa terisi otomatis sesuai tanggal dan tetap bisa diubah manual.","Biaya pencairan (administrasi, provisi, materai, transfer, lain-lain) kini otomatis dipotong sesuai Tarif & Pajak. Simulasi menampilkan rincian biaya dan dana bersih yang diterima nasabah.","Untuk mengecualikan satu biaya, hilangkan centangnya di Setelan > Simpan Pinjam."]},
 {v:"1.1.053",d:"2026-10-03",t:"Riwayat portal per nasabah dan petunjuk PIN",i:["Di rincian nasabah ada bagian Riwayat portal: status PIN, waktu masuk terakhir, apakah akun terkunci, dan 10 catatan terakhir (PIN diatur atau diganti, masuk berhasil, percobaan gagal).","Saat mengedit nasabah yang sudah punya PIN, kolom PIN kini bertuliskan PIN sudah diatur (kosongkan bila tidak diganti), jadi tidak lagi terlihat seperti belum ada PIN."]},
 {v:"1.1.052",d:"2026-10-03",t:"Bobot skor kelayakan dapat diatur",i:["Di Setelan > Profil > Alur Pengajuan Lengkap ada tiga bobot skor kelayakan: rasio angsuran, nilai jaminan, dan verifikasi. Bawaannya 40/30/30 dan hasil lama tidak berubah. Atur sesuai kebijakan BUMDes; skor dihitung ulang sebagai persentase dari total bobot.","Analisis yang sudah tersimpan tetap memakai skor lamanya."]},
 {v:"1.1.051",d:"2026-10-03",t:"Tombol Terbitkan tagihan menempel di bawah",i:["Di Baca Meter, tombol Terbitkan tagihan kini selalu terlihat di bagian bawah layar selagi Anda mengisi angka meter, tanpa perlu menggulir kembali ke atas."]},
 {v:"1.1.050",d:"2026-10-03",t:"Konfirmasi sebelum aksi berisiko",i:["Terbitkan tagihan air, Akui fee pencairan, dan Hapus logo kini meminta konfirmasi dulu. Dialog menyebutkan akibatnya (misalnya jumlah tagihan yang akan diposting), dan tidak ada yang berubah sebelum Anda memilih Ya."]},
 {v:"1.1.049",d:"2026-10-02",t:"Tombol + melayang lebih pintar",i:["Di Simpan Pinjam, tombol + kini langsung membuka form Ajukan pinjaman; di halaman lain membuka Transaksi baru.","Tombol tidak tampil di halaman yang tidak membutuhkannya (Laporan, Buku Besar, Neraca Saldo, Setelan, Data, Transaksi) atau bila peran Anda tidak berhak.","Tombol menepi saat Anda menggulir ke bawah atau mengetik di kolom isian, sehingga tidak menutupi isi, dan muncul lagi saat menggulir ke atas."]},
 {v:"1.1.048",d:"2026-10-02",t:"Riwayat cadangan dan pulihkan versi dari awan",i:["Di Setelan > Awan ada tombol Riwayat cadangan: daftar 30 versi terakhir yang tersimpan di awan, lengkap dengan waktunya. Pilih Pulihkan untuk mengembalikan data ke versi itu.","Sebelum memulihkan, aplikasi meminta konfirmasi dan menyimpan salinan data perangkat saat ini. Hasil pemulihan baru masuk awan sebagai versi terbaru setelah Anda klik Simpan ke awan."]},
 {v:"1.1.047",d:"2026-10-02",t:"Panduan Supabase dilengkapi",i:["Panduan SUPABASE.md kini menjelaskan cara menambah pengurus, peran, mematikan pendaftaran publik, dan kebiasaan aman saat memakai beberapa perangkat."]},
 {v:"1.1.046",d:"2026-10-02",t:"Pesan hasil sinkron tampil dekat tombol",i:["Di Setelan > Awan, hasil Simpan ke awan, Muat dari awan, dan pesan galat kini muncul tepat di bagian Sinkron, jadi tidak perlu menggulir ke atas."]},
 {v:"1.1.045",d:"2026-10-02",t:"Perbaikan Simpan ke awan setelah memilih ulang BUMDes",i:["Memilih ulang BUMDes di Setelan > Awan tidak lagi membuat sinkron terjeda dengan pesan data di awan sudah berubah. Bila sudah terlanjur terjeda, pakai Muat dari awan atau Timpa awan."]},
 {v:"1.1.044",d:"2026-10-02",t:"Nama BUMDes di header ikut BUMDes awan",i:["Saat memilih atau membuat BUMDes di Setelan > Awan, nama BUMDes di header dan laporan otomatis disamakan dengan nama di awan."]},
 {v:"1.1.043",d:"2026-10-02",t:"Kunci Supabase format baru didukung",i:["Kolom Anon key di Setelan > Awan kini menerima kunci berawalan sb_publishable_ (format baru Supabase). Kunci rahasia (sb_secret_ atau service_role) ditolak demi keamanan."]},
 {v:"1.1.042",d:"2026-10-02",t:"Cadangan dan sinkron data ke awan (Supabase)",i:["Data BUMDes kini bisa dicadangkan ke Supabase milik Anda: Setelan > Awan. Isi alamat proyek dan anon key, masuk dengan akun pengurus, lalu Simpan ke awan atau Muat dari awan. Tersedia 30 riwayat cadangan.","Bila perangkat lain sudah menyimpan lebih baru, sinkron dijeda dan Anda memilih Muat dari awan atau Timpa awan, sehingga data tidak saling menimpa tanpa sengaja.","Ada opsi Simpan otomatis. Panduan pemasangan dan berkas SQL ada di SUPABASE.md dan supabase_schema.sql."]},
 {v:"1.1.041",d:"2026-10-02",t:"Portal nasabah lebih lega dan ada tombol kembali",i:["Halaman masuk portal punya tombol Kembali ke aplikasi, sehingga pengurus tidak terjebak di layar masuk.","Tampilan portal diberi ruang tepi dan jarak antarkartu yang lebih lega di HP maupun komputer."]},
 {v:"1.1.040",d:"2026-10-02",t:"PIN portal langsung dari formulir nasabah",i:["Saat portal nasabah aktif, formulir nasabah (baru maupun edit) punya kolom PIN portal. Isi nomor telepon dan PIN 4–8 angka, simpan, dan nasabah langsung bisa masuk portal.","Nomor telepon wajib diisi dan tidak boleh sama dengan nasabah aktif lain agar akun tidak tertukar. Kosongkan kolom PIN bila nasabah belum perlu akses."]},
 {v:"1.1.039",d:"2026-10-02",t:"Portal Nasabah mudah ditemukan di Setelan",i:["Pengaturan portal nasabah kini punya sub-tab sendiri di Setelan: Portal Nasabah (sebelumnya terselip di bagian bawah Profil).","Di sana ada saklar Aktif/Mati, jumlah nasabah yang sudah punya PIN, dan tombol Buka halaman masuk. PIN nasabah diatur dari rincian nasabah di Master."]},
 {v:"1.1.038",d:"2026-10-02",t:"Portal nasabah (tampilan demo)",i:["Ada tampilan khusus nasabah: masuk dengan nomor HP dan PIN, lalu melihat tagihan berikutnya, pinjaman beserta jadwal angsuran, tabungan beserta mutasi, dan profil. Semuanya hanya baca dan hanya data miliknya sendiri.","Aktifkan di Setelan > Portal Nasabah. PIN diatur pengurus dari rincian nasabah (PIN portal), disimpan terenkripsi, dan akun terkunci 5 menit setelah 5 kali salah. Nasabah bisa mengganti PINnya sendiri.","Pengurus bisa melihat tampilannya lewat Pratinjau portal di rincian nasabah. Alamat masuk: tambahkan #portal di akhir alamat aplikasi.","Ini masih mode demo tanpa server: data hanya ada di perangkat ini, jadi belum bisa dipakai nasabah dari HP mereka sendiri."]},
 {v:"1.1.037",d:"2026-10-02",t:"Produk tabungan dan deposito",i:["Di Setelan > Produk Tabungan dan Deposito Anda bisa membuat produk dengan bunga sendiri. Rekening dengan produk itu memakai bunganya sendiri, bukan bunga dasar.","Bila jangka (bulan) diisi, produk menjadi deposito: jatuh tempo dihitung otomatis, tidak bisa ditarik sebelum jatuh tempo, dan tidak menerima setoran tambahan.","Bunga dan jangka dikunci saat rekening dibuka, jadi mengubah atau menghapus produk tidak memengaruhi rekening lama. Jatuh tempo tampil di daftar, rincian, dan buku tabungan."]},
 {v:"1.1.036",d:"2026-10-02",t:"Fee pencairan bisa diamortisasi",i:["Di Setelan > Pengakuan Fee Pencairan Anda bisa memilih biaya pencairan diakui langsung sebagai pendapatan, atau ditangguhkan lalu diakui per bulan sepanjang tenor pinjaman. Pilihan berlaku untuk pencairan berikutnya.","Fee ikut diakui otomatis tiap ada pembayaran angsuran, dan tombol Akui fee sampai hari ini mengakui semuanya sekaligus. Sisa fee langsung diakui penuh saat pinjaman lunas atau dihapus buku.","Membatalkan pencairan ikut membalik pengakuan fee. Laporan Simpan Pinjam menampilkan saldo fee yang masih ditangguhkan."]},
 {v:"1.1.035",d:"2026-10-02",t:"Batas nominal untuk persetujuan restrukturisasi",i:["Di Setelan > Pemisahan Tugas ada kolom batas sisa pokok untuk aturan dua orang restrukturisasi. Pinjaman dengan sisa pokok di bawah batas langsung direstrukturisasi oleh satu orang; yang di atas batas tetap butuh usulan dan persetujuan pengguna lain.","Isi 0 bila aturan harus berlaku untuk semua pinjaman. Usulan yang sudah menunggu tetap harus diputuskan walau batas dinaikkan."]},
 {v:"1.1.034",d:"2026-10-02",t:"Calon langsung diajukan pinjaman",i:["Dari calon yang sudah menjadi nasabah, tombol Ajukan pinjaman kini mengisi pokok otomatis dari rencana pinjaman calon.","Pengajuan atau draf yang dibuat dari sana tercatat berasal dari calon tersebut, dan muncul di rincian calon sebagai Pengajuan dari calon ini."]},
 {v:"1.1.033",d:"2026-10-02",t:"Tampilan form lebih seragam",i:["Dropdown, kalender tanggal, pilihan bulan, tombol pilih berkas, kotak centang, dan daftar berpoin kini memakai tampilan aplikasi sendiri, bukan bawaan browser.","Di HP, pilihan terbuka sebagai lembar dari bawah dengan tombol besar; di komputer muncul sebagai kotak kecil di bawah isian.","Dropdown panjang punya kolom cari. Kalender punya tombol Hari ini, Hapus, dan pindah bulan; tanggal di luar batas otomatis nonaktif. Bisa dipakai dengan keyboard."]},
 {v:"1.1.032",d:"2026-10-02",t:"Pengajuan bisa disimpan sebagai draf",i:["Di formulir pengajuan pinjaman ada tombol Simpan sebagai draf. Draf belum masuk antrean persetujuan, belum bernomor pinjaman, dan tidak membuat jadwal atau jurnal.","Dari rincian draf Anda bisa mengubah, mengirim pengajuan (isian diperiksa ulang terhadap batas yang berlaku lalu mendapat nomor pinjaman), atau menghapus draf.","Laporan Simpan Pinjam ikut menghitung draf di pipeline pengajuan."]},
 {v:"1.1.031",d:"2026-10-02",t:"Calon peminjam sebelum menjadi nasabah",i:["Simpan Pinjam punya sub-tab baru Calon: catat calon peminjam (nama, telepon, alamat, keperluan, rencana pinjaman) sebelum mereka menjadi nasabah.","Status calon: Baru, Diproses, Lolos, atau Ditolak (wajib beralasan, bisa dibuka kembali). Setiap perubahan tercatat di riwayat calon.","Calon yang Lolos bisa dijadikan nasabah dengan satu tombol (data tersalin), lalu langsung lanjut Ajukan pinjaman. Laporan Simpan Pinjam menampilkan jumlah calon per status dan tingkat konversinya."]},
 {v:"1.1.030",d:"2026-10-02",t:"Restrukturisasi bisa butuh dua orang",i:["Di Setelan > Pemisahan Tugas ada aturan baru: restrukturisasi butuh dua orang. Bila aktif (dan Mode Pengguna menyala), restrukturisasi hanya berupa usulan sampai disetujui pengguna lain.","Pengusul tidak boleh menyetujui usulannya sendiri. Penyetuju melihat isian dari usulan dan boleh menyesuaikannya, lalu jadwal angsuran baru dibuat. Usulan juga bisa ditolak.","Pengusul dan penyetuju tercatat di riwayat restrukturisasi dan audit log. Bila aturan mati, cara kerja lama tetap berlaku."]},
 {v:"1.1.029",d:"2026-10-02",t:"Pajak atas biaya administrasi tabungan",i:["Biaya administrasi tabungan bulanan kini ikut dikenai pajak bila tarifnya ditandai kena pajak di Master > Tarif & Pajak. Saldo nasabah berkurang sebesar biaya ditambah pajak.","Saat proses akhir bulan, kartu konfirmasi menampilkan biaya dan pajaknya. Rekening dilewati bila saldonya tidak cukup untuk biaya ditambah pajak (setelah saldo minimum).","Laporan Simpan Pinjam menampilkan pajak biaya tabungan yang belum disetor. Membatalkan biaya otomatis ikut membalik pajaknya."]},
 {v:"1.1.028",d:"2026-10-02",t:"Waktu proses per tahap di laporan",i:["Laporan Simpan Pinjam kini menampilkan waktu proses tiap tahap: pengajuan, verifikasi, analisis, persetujuan, akad, dan pencairan, lengkap dengan rata-rata dan waktu terlama dalam hari.","Tahap verifikasi, analisis, dan akad muncul bila alur lengkap dipakai. Tersedia juga total waktu dari pengajuan sampai pencairan. Pinjaman saldo awal tidak dihitung."]},
 {v:"1.1.027",d:"2026-10-02",t:"Audit Log dengan nama peristiwa baku",i:["Audit Log punya kolom Peristiwa dengan kode baku seperti PINJAMAN.CAIR, PINJAMAN.BAYAR_BATAL, atau TAHUN_BUKU.TUTUP, sehingga kejadian yang sama selalu bernama sama.","Kolom Peristiwa juga ikut di unduhan CSV, dan kodenya bisa dipakai di kotak pencarian (misalnya ketik pinjaman.cair)."]},
 {v:"1.1.026",d:"2026-10-02",t:"Laporan biaya per kode",i:["Laporan Simpan Pinjam kini punya tabel Biaya per kode: total biaya dan pajak tiap kode (administrasi, provisi, pelunasan dipercepat, restrukturisasi, dll.) dipisah menurut sumbernya: pencairan, pelunasan dipercepat, atau restrukturisasi.","Hanya transaksi yang masih berlaku yang dihitung; pencairan, pelunasan, atau restrukturisasi yang dibatalkan tidak ikut. Mengikuti rentang tanggal dan unit yang dipilih.","Pelunasan dipercepat mulai sekarang menyimpan rincian kodenya; data lama tetap dihitung dengan kode \"-\"."]},
 {v:"1.1.025",d:"2026-10-02",t:"Saldo Awal Terpandu lebih mudah dan aman",i:["Bagian atas menampilkan total piutang pelanggan dan pinjaman berjalan awal, serta daftar langkah yang sudah dan belum dikerjakan.","Saat mengisi formulir muncul pratinjau langsung: jurnal yang akan dicatat, angsuran pertama, total jasa, dan peringatan bila angsuran pertama sudah lewat jatuh tempo.","Formulir dapat dilipat (otomatis terlipat setelah ada data), daftar punya baris Total, dan ada petunjuk bila pelanggan atau nasabah belum terdaftar.","Validasi lebih ketat: tanggal saldo tidak boleh melewati hari ini, jasa maksimal 100% per tahun, tenor maksimal 360 angsuran."]},
 {v:"1.1.024",d:"2026-10-02",t:"Akad cetak dengan tarif yang dibekukan",i:["Pinjaman yang sudah punya akad punya tombol Cetak akad: dokumen perjanjian berisi para pihak, pokok, jasa, tenor, biaya pencairan dan pajak, biaya pelunasan dipercepat, denda, jaminan, jadwal angsuran, dan ketentuan lain.","Angka biaya, pajak, dan denda dibekukan saat akad dicatat, jadi perubahan tarif sesudahnya tidak mengubah isi akad yang sudah dibuat.","Di Setelan ada kotak Klausul Akad untuk ketentuan tambahan (satu per baris). Aplikasi tidak menyediakan klausul bawaan; isinya perlu ditinjau secara hukum oleh pengurus."]},
 {v:"1.1.023",d:"2026-10-02",t:"Bunga tabungan bertingkat dan cetak buku tabungan",i:["Di Setelan > Tabungan bisa menambah tingkat bunga menurut saldo (misalnya saldo mulai Rp 1.000.000 berbunga lebih tinggi). Bunga dihitung harian memakai tingkat yang tercapai pada hari itu.","Rekening tabungan punya tombol Cetak buku: halaman buku tabungan berisi data nasabah, seluruh mutasi (kredit, debit, saldo), dan saldo akhir, siap dicetak."]},
 {v:"1.1.022",d:"2026-10-02",t:"Biaya dan pajak dipotong saat pencairan",i:["Di Setelan > Simpan Pinjam kini bisa memilih biaya (administrasi, provisi, materai, transfer, dll.) yang dipotong saat pinjaman dicairkan.","Saat mencairkan, aplikasi menampilkan potongan biaya, pajak, dan dana bersih yang diterima nasabah, dan semuanya tercatat dalam satu jurnal.","Bukti pencairan memuat rincian potongan dan dana bersih. Membatalkan pencairan ikut membalik biaya dan pajaknya."]},
 {v:"1.1.021",d:"2026-10-02",t:"Audit lebih lengkap dan laporan Simpan Pinjam bertambah",i:["Audit Log kini menampilkan nilai sebelum dan sesudah untuk perubahan setelan, data nasabah, dan tarif/pajak, serta bisa diunduh sebagai CSV sesuai filter yang aktif.","Modal pinjaman punya bagian Jejak audit: semua kejadian pada pinjaman itu (pembayaran, restrukturisasi, hapus buku, dan lain-lain) beserta pelakunya.","Laporan Simpan Pinjam menambah pipeline pengajuan per tahap, waktu proses rata-rata, kolektibilitas, pendapatan per jenis, pajak yang masih terutang, dan kepatuhan pemisahan tugas."]},
 {v:"1.1.020",d:"2026-10-02",t:"Pelunasan, restrukturisasi, dan hapus buku lebih lengkap",i:["Pelunasan dipercepat kini bisa dikenai biaya dan pajak. Rinciannya tampil sebelum Anda konfirmasi dan tercetak di kwitansi. Biaya diatur di Setelan > Simpan Pinjam.","Biaya restrukturisasi juga bisa dikenai pajak, dan restrukturisasi terakhir kini bisa dibatalkan selama belum ada pembayaran pada jadwal barunya.","Hapus buku dapat diatur agar butuh dua orang: satu mengusulkan, yang lain menyetujui (Setelan > Pemisahan Tugas).","Perbaikan: pembatalan pembayaran setelah restrukturisasi tidak lagi salah ditolak."]},
 {v:"1.1.019",d:"2026-10-02",t:"Halaman Simpan Pinjam + tabungan; restrukturisasi, hapus buku",i:["Halaman dinamai Simpan Pinjam (menu bawah ikut); sub-tab Tabungan kini tepat setelah Pinjaman; Ringkasan memuat kartu Tabungan (total, setoran dan penarikan bulan ini) dan tombol Buka rekening.","Daftar nasabah menampilkan saldo tabungan; modal nasabah memuat tabungan dan tombol Buka rekening yang sudah memilih nasabah.","Restrukturisasi pinjaman: sisa pokok dijadwalkan ulang (jasa, tenor, metode baru), jadwal lama diarsipkan, jasa/denda tertunggak dihapus atau dibayar dulu, biaya dari Tarif & Pajak; pembayaran dan pencairan lama tidak dapat dibatalkan sesudahnya.","Hapus buku kredit Macet (Dr 5700, Cr 1300) dan pencatatan pemulihan (pendapatan 4600); izin sp.restruk dan sp.hapusbuku tidak ikut sp.kelola."]},
 {v:"1.1.018",d:"2026-10-01",t:"Kolektibilitas dan tindak lanjut penagihan",i:["Kolektibilitas pinjaman aktif: Lancar, Dalam Perhatian, Kurang Lancar, Diragukan, Macet menurut hari terlambat terlama; batas hari diatur di Setelan (bawaan 30/90/180 hari, asumsi teknis).","Sub-tab Tunggakan menjadi daftar kerja penagihan: satu baris per pinjaman, diurutkan dari jenjang terburuk, dengan filter dan tindak lanjut terakhir (janji lewat ditandai), plus ringkasan kolektibilitas.","Catatan tindak lanjut (telepon, WhatsApp, kunjungan, surat) dengan hasil dan janji bayar dari modal pinjaman; izin baru sp.tagih."]},
 {v:"1.1.017",d:"2026-10-01",t:"Tabungan: bunga otomatis, biaya, pajak",i:["Setelan > Tabungan: bunga per tahun, kode biaya administrasi bulanan, kode pajak bunga, dan ambang pajak.","Sub-tab Tabungan: tombol Proses akhir bulan menghitung bunga dari saldo harian (÷ 365) dan memotong biaya administrasi; ada konfirmasi berisi bruto, pajak, dan bersih.","Bulan yang sama tidak diproses dua kali; rekening yang saldonya kurang untuk biaya dilewati; tiap mutasi dapat dibatalkan.","Jurnal: bunga ke akun 5600, pajak ke 2210, biaya ke pendapatan 4500; buku tabungan menampilkan bruto dan pajak."]},
 {v:"1.1.016",d:"2026-10-01",t:"Peran Simpan Pinjam dan pemisahan tugas",i:["Izin per tahap: ajukan, verifikasi, analisis, setujui, akad, cairkan, bayar, dan data (nasabah/jaminan/rekening tabungan); izin lama Simpan Pinjam (sp.kelola) tetap mencakup semuanya.","Peran baru: Petugas Kredit, Surveyor/Analis, Approver/Manajer, Kasir; Direktur kini dapat menyetujui. Data lama otomatis mendapat peran baru (izin dapat diubah di Setelan).","Pemisahan tugas (Setelan, bawaan mati, berlaku saat Mode Pengguna aktif): pengaju ≠ penyetuju, penganalisis ≠ penyetuju, penyetuju ≠ pencair; pelanggaran ditolak dan dicatat di audit log."]},
 {v:"1.1.015",d:"2026-10-01",t:"Ringkasan nasabah yang dapat dibagikan",i:["Modal nasabah: tombol Bagikan ringkasan membuat teks posisi pinjaman (sisa pokok, tunggakan, angsuran berikut) dan tabungan (saldo, mutasi terakhir).","Tombol Salin, WhatsApp (nomor telepon nasabah dinormalkan ke 62…), dan Bagikan bila perangkat mendukung; setiap pembagian tercatat di audit log.","Data adalah posisi saat teks dibuat; berisi data pribadi, kirim hanya ke nasabah yang bersangkutan."]},
 {v:"1.1.014",d:"2026-10-01",t:"Tabungan nasabah",i:["Sub-tab Tabungan di Simpan Pinjam: buka rekening per nasabah, setoran, penarikan, dan bunga tabungan, lengkap dengan buku tabungan (mutasi dan saldo berjalan).","Uang nasabah dicatat sebagai utang BUMDes (akun 2300 Tabungan Nasabah); penarikan tidak boleh melebihi saldo dikurangi saldo minimum dan kas/bank harus cukup.","Mutasi bisa dibatalkan dengan jurnal pembalik (tidak bila saldo menjadi negatif); rekening ditutup bila saldo nol.","Ringkasan menampilkan total tabungan; daftar dicocokkan dengan buku besar akun 2300; Arus Kas memasukkan tabungan ke Pendanaan."]},
 {v:"1.1.013",d:"2026-10-01",t:"Peran Superadmin",i:["Peran baru Superadmin (pengembang sistem) dengan akses penuh; izinnya selalu lengkap, termasuk izin baru di rilis berikutnya, dan tidak dapat diubah.","Tersembunyi bagi peran lain: Admin Sistem tidak melihat, menonaktifkan, mereset PIN, atau menunjuk Superadmin.","Data lama otomatis mendapat peran ini."]},
 {v:"1.1.012",d:"2026-10-01",t:"Master ringkas dengan modal rincian",i:["Master Unit, Kas & Bank, COA, Pihak, Pegawai, dan Tarif & Pajak memakai daftar ringkas; klik baris membuka modal rincian.","Tombol Ubah dan Nonaktifkan/Aktifkan ada di modal rincian; versi baru tarif dari modal tarif.","Tanggal di semua modal tampil dd/mm/yyyy."]},
 {v:"1.1.011",d:"2026-10-01",t:"Istilah Void diganti Batalkan",i:["Tombol, konfirmasi, status, dan pesan pembatalan transaksi memakai kata Batalkan dan Dibatalkan, bukan Void.","Fungsi tidak berubah: jurnal pembalik dibuat dan transaksi asli tetap tercatat."]},
 {v:"1.1.010",d:"2026-10-01",t:"Ubah transaksi dari modal rincian",i:["Tombol Ubah di modal rincian transaksi (penerimaan, pengeluaran, transfer, jurnal manual): form terisi dari jurnal.","Menyimpan perubahan membuat jurnal pembalik untuk transaksi lama dan memposting yang baru; keduanya saling bertaut dan riwayat tetap tercatat.","Periode tertutup atau unit di luar tugas menolak ubah, tanpa mengubah data."]},
 {v:"1.1.009",d:"2026-10-01",t:"Transaksi ringkas dengan modal",i:["Daftar transaksi dibuat ringkas seperti daftar pinjaman; klik baris membuka modal rincian berisi data, jurnal (termasuk jurnal pembalik), dan tombol Void.","Transaksi Baru dan Jurnal Multi-baris kini berupa modal; sub-tab Transaksi hanya Transaksi dan Saldo Awal.","Jalan pintas Catat Penerimaan/Pengeluaran di Dashboard langsung membuka modal."]},
 {v:"1.1.008",d:"2026-10-01",t:"Alur pengajuan lengkap (opsional)",i:["Setelan > Profil: Alur Pengajuan Lengkap (bawaan mati). Bila aktif: verifikasi dan survei, analisis kelayakan, akad sebelum cair.","Persetujuan: harus Lolos verifikasi dan ada analisis; pokok di atas batas Manajer memerlukan hak Persetujuan besar bila mode pengguna aktif.","Linimasa pinjaman memuat verifikasi, analisis, dan akad."]},
 {v:"1.1.007",d:"2026-10-01",t:"Master Tarif & Biaya (berversi) dan mesin hitung fee/pajak",i:["Master > Tarif & Biaya: daftar tarif dan pajak berversi; versi baru menutup versi lama, riwayat tidak berubah.","Metode: persentase, nominal tetap, per hari, per bulan; dasar pokok/sisa pokok/angsuran/tunggakan; minimum–maksimum; pajak per fee.","Pratinjau hitung menurut tanggal transaksi. Belum dipakai oleh pencairan/pembayaran."]},
 {v:"1.1.006",d:"2026-10-01",t:"Pratinjau peringatan pengajuan, uji alur lengkap",i:["Form pengajuan menampilkan peringatan (pengajuan identik, batas pinjaman berjalan, batas total pokok) langsung saat diisi, sebelum tombol dikirim.","Uji ujung ke ujung alur ajukan → setujui → cairkan → bayar → linimasa."]},
 {v:"1.1.005",d:"2026-10-01",t:"Rincian pinjaman: linimasa dan jaminan",i:["Modal pinjaman menampilkan Linimasa (diajukan, disetujui, dicairkan, pembayaran, pembatalan, lunas) lengkap dengan pelaku.","Jaminan pinjaman tampil di modal; Tambah jaminan langsung dari pinjaman lalu kembali ke rincian.","Baris baru: Tagihan berikutnya, Denda berjalan, Total dibayar."]},
 {v:"1.1.004",d:"2026-10-01",t:"Ringkasan Simpan Pinjam, urutan daftar, simulasi angsuran",i:["Sub-tab Ringkasan (tab bawaan): pinjaman aktif dan sisa pokok, tunggakan, jatuh tempo 7/30 hari, pengajuan menunggu, pembayaran bulan ini; kartu menuju daftar yang sesuai.","Daftar pinjaman: urutan (terbaru, terlama, pokok terbesar, sisa pokok, menunggak dulu) dan Muat lebih banyak.","Modal pengajuan: simulasi angsuran langsung (angsuran, total jasa, total bayar, jasa efektif, jadwal).","Nasabah: kolom sisa pokok, lencana Menunggak, tombol Ajukan pinjaman dari rincian nasabah."]},
 {v:"1.1.003",d:"2026-10-01",t:"Tombol ? Catatan rilis di Setelan",i:["Tombol ? di Setelan membuka modal catatan rilis; rilis terbaru terbuka, rilis lama bisa dibuka satu per satu."]},
 {v:"1.1.002",d:"2026-10-01",t:"Perbaikan ikon gembok periode",i:["Data → Periode: periode yang sudah ditutup kini memakai ikon gembok terbuka (aksi Buka); periode terbuka memakai gembok tertutup (aksi Tutup)."]},
 {v:"1.1.001",d:"2026-10-01",t:"PWA, skema versi baru, kode dipecah",i:["Aplikasi dapat dipasang dari browser (PWA) dan tetap terbuka tanpa internet bila di-host lewat https.","Skema versi baru 1.1.NNN; catatan rilis lengkap di release_notes.md.","Kode dipecah menjadi berkas bernama jelas (index.html, style.css, app.js, loans.js, dst.)."]},
 {v:"0.1.049",d:"2026-10-01",t:"Kode dipecah menjadi berkas sumber",i:["Berkas sumber terpisah dan perakit build.js untuk bumdes.html satu-file."]},
 {v:"0.1.048",d:"2026-10-01",t:"Tombol bayar di kartu pembayaran",i:["Tombol utama Bayar angsuran / bunga / nominal ke-N langsung di kartu pembayaran."]},
 {v:"0.1.047",d:"2026-10-01",t:"Jenis pembayaran angsuran",i:["Pilihan jenis: pokok + bunga, bunga saja, atau nominal bebas, dengan jumlah terisi otomatis."]},
 {v:"0.1.046",d:"2026-10-01",t:"Tunggakan, Jaminan, Nasabah ringkas",i:["Tiga sub-tab memakai daftar ringkas + modal rincian, dengan pencarian dan filter.","Form tambah jaminan pindah ke modal."]},
 {v:"0.1.045",d:"2026-10-01",t:"Daftar pinjaman ringkas + modal rincian",i:["Klik baris pinjaman membuka modal berisi aksi, jadwal pembayaran yang bisa dibuka/ditutup, dan riwayat pembayaran."]},
 {v:"0.1.044",d:"2026-10-01",t:"Penyegaran tampilan",i:["Tampilan lebih modern, ringkas, dan bersih; mode gelap ikut."]},
 {v:"0.1.043",d:"2026-10-01",t:"Form pengajuan pinjaman dalam modal",i:["Pengajuan pinjaman memakai modal."]},
 {v:"0.1.042",d:"2026-10-01",t:"Dashboard",i:["Dashboard dioptimalkan; kartu Piutang Pinjaman dan Tunggakan dapat diklik."]},
 {v:"0.1.041",d:"2026-10-01",t:"Mesin hitung jasa dan denda",i:["Jasa flat/anuitas, denda (masa tenggang, dasar hitung, batas), pembulatan; diatur di Setelan."]},
 {v:"0.1.040",d:"2026-10-01",t:"Validasi pengajuan dan konfirmasi aksi",i:["Batas pinjaman, peringatan data identik, konfirmasi Setujui/Cairkan, alasan wajib saat tolak/batal."]}
];
function vRelease(){const r=RELEASES[0];return `<h3>v${esc(r.v)} <span class="k">${esc(r.d)}</span></h3><p><b>${esc(r.t)}</b></p><ul>${r.i.map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`}
function rnBar(){return`<div class="rnb"><span class="k">Versi ${esc(APP_VER)}</span><button class="ib s" title="Catatan rilis" aria-label="Catatan rilis" onclick="mdOpen('rn','')">${ic("help")}<span>Catatan rilis</span></button></div>`}
